 "cues": [
  {
   "id": "v1a",
   "who": "both",
   "kind": "sing",
   "start": 9.55,
   "end": 13.2,
   "text": "אֲנִי וְאַתָּה נִמְכֹּר אֲוִיר לְכֻלָּם,",
   "syll": 8
  },
  {
   "id": "v1b",
   "who": "T",
   "kind": "sing",
   "start": 13.79,
   "end": 17.9,
   "text": "אֲנִי וְאַתָּה, בְּמִנּוּי מֻשְׁלָם.",
   "syll": 7
  },
  {
   "id": "v1c",
   "who": "S",
   "kind": "sing",
   "start": 17.95,
   "end": 19.44,
   "text": "וְאִם יִשְׁאֲלוּ מַה קַיָּם —",
   "syll": 6
  },
  {
   "id": "v1d",
   "who": "T",
   "kind": "sing",
   "start": 20.0,
   "end": 21.42,
   "text": "נַגִּיד: זֶה שָׁם.",
   "syll": 4
  },
  {
   "id": "v1e",
   "who": "both",
   "kind": "sing",
   "start": 22.19,
   "end": 25.54,
   "text": "אֲנִי וְאַתָּה נְשַׁגֵּעַ אֶת הָעוֹלָם.",
   "syll": 10
  },
  {
   "id": "s1a",
   "who": "T",
   "kind": "speak",
   "start": 26.7,
   "end": 27.68,
   "text": "קִבַּלְנוּ מִילְיוֹן!",
   "syll": 5
  },
  {
   "id": "s1b",
   "who": "S",
   "kind": "speak",
   "start": 28.47,
   "end": 29.53,
   "text": "הַכֶּסֶף נִכְנַס?",
   "syll": 5
  },
  {
   "id": "s1c",
   "who": "T",
   "kind": "speak",
   "start": 30.01,
   "end": 31.63,
   "text": "לֹא, אֲבָל יֵשׁ רֵאָיוֹן.",
   "syll": 6
  },
  {
   "id": "s1d",
   "who": "S",
   "kind": "speak",
   "start": 32.18,
   "end": 33.73,
   "text": "אָז מִי מְשַׁלֵּם עַל הַמָּזוֹן?",
   "syll": 8
  },
  {
   "id": "s1e",
   "who": "T",
   "kind": "speak",
   "start": 34.58,
   "end": 37.0,
   "text": "אִמָּא. הִיא גֵּאָה בִּי הָמוֹן.",
   "syll": 8
  },
  {
   "id": "v2a",
   "who": "both",
   "kind": "sing",
   "start": 37.96,
   "end": 41.57,
   "text": "אֲנִי וְאַתָּה, כְּבָר כָּתְבוּ בָּעִתּוֹן,",
   "syll": 9
  },
  {
   "id": "v2b",
   "who": "both",
   "kind": "sing",
   "start": 42.17,
   "end": 46.26,
   "text": "אֲנִי וְאַתָּה — שְׁנֵי חֲמוֹרִים עִם חָזוֹן.",
   "syll": 9
  },
  {
   "id": "v2c",
   "who": "S",
   "kind": "sing",
   "start": 46.3,
   "end": 47.89,
   "text": "שָׁאֲלוּ: וּמַה עִם הַהוֹן?",
   "syll": 7
  },
  {
   "id": "v2d",
   "who": "T",
   "kind": "sing",
   "start": 47.92,
   "end": 50.0,
   "text": "הָלַךְ עַל הַסִּרְטוֹן.",
   "syll": 6
  },
  {
   "id": "v2e",
   "who": "both",
   "kind": "sing",
   "start": 50.58,
   "end": 55.65,
   "text": "אֲנִי וְאַתָּה מְגַיְּסִים עוֹד מִילְיוֹן.",
   "syll": 8
  },
  {
   "id": "s2a",
   "who": "T",
   "kind": "speak",
   "start": 56.01,
   "end": 58.62,
   "text": "הַמַּשְׁקִיעַ פֹּה. תּוֹצִיא אֶת הַקַּשׁ מֵהַפֶּה.",
   "syll": 13
  },
  {
   "id": "s2b",
   "who": "S",
   "kind": "speak",
   "start": 59.11,
   "end": 61.54,
   "text": "לָמָּה? זֶה דַּוְקָא נִרְאֶה דֵּי יָפֶה.",
   "syll": 10
  },
  {
   "id": "s2c",
   "who": "T",
   "kind": "speak",
   "start": 62.55,
   "end": 64.03,
   "text": "עוֹד לֹא קִבַּלְנוּ הַשְׁקָעָה —",
   "syll": 8
  },
  {
   "id": "s2d",
   "who": "T",
   "kind": "speak",
   "start": 64.55,
   "end": 66.4,
   "text": "כְּבָר רוֹאִים עָלֶיךָ הוֹצָאָה.",
   "syll": 9
  },
  {
   "id": "v3a",
   "who": "T",
   "kind": "sing",
   "start": 66.6,
   "end": 69.7,
   "text": "אֲנִי וְאַתָּה מוֹכְרִים עוֹד מְנָיוֹת,",
   "syll": 8
  },
  {
   "id": "v3b",
   "who": "both",
   "kind": "sing",
   "start": 70.56,
   "end": 74.7,
   "text": "אֲנִי וְאַתָּה, מְסֻדָּרִים לְדוֹרוֹת.",
   "syll": 8
  },
  {
   "id": "v3c",
   "who": "S",
   "kind": "sing",
   "start": 74.75,
   "end": 76.24,
   "text": "שָׁאֲלוּ: וּמַה עִם הַהַכְנָסוֹת?",
   "syll": 9
  },
  {
   "id": "v3d",
   "who": "T",
   "kind": "sing",
   "start": 76.57,
   "end": 78.4,
   "text": "תִּרְאוּ מַצָּגוֹת.",
   "syll": 5
  },
  {
   "id": "v3e",
   "who": "both",
   "kind": "sing",
   "start": 78.94,
   "end": 85.03,
   "text": "אֲנִי וְאַתָּה כְּבָר פּוֹתְחִים עוֹד חֲבָרוֹת.",
   "syll": 9
  },
  {
   "id": "o1",
   "who": "T",
   "kind": "speak",
   "start": 86.08,
   "end": 89.43,
   "text": "מָכַרְנוּ בְּמִילְיוֹן! נִגְמְרוּ הַדְּאָגוֹת!",
   "syll": 10
  },
  {
   "id": "o2",
   "who": "S",
   "kind": "speak",
   "start": 90.0,
   "end": 91.34,
   "text": "הוּא שִׁלֵּם בִּמְזֻמָּן?",
   "syll": 6
  },
  {
   "id": "o3",
   "who": "T",
   "kind": "speak",
   "start": 91.85,
   "end": 93.33,
   "text": "יוֹתֵר טוֹב. בִּמְנָיוֹת.",
   "syll": 6
  },
  {
   "id": "o4",
   "who": "S",
   "kind": "speak",
   "start": 93.85,
   "end": 95.63,
   "text": "וּמַה הַחֶבְרָה שֶׁלּוֹ מוֹכֶרֶת?",
   "syll": 10
  },
  {
   "id": "o5",
   "who": "T",
   "kind": "speak",
   "start": 96.0,
   "end": 98.23,
   "text": "גַּם אֲוִיר. בַּאֲרִיזָה אַחֶרֶת.",
   "syll": 8
  },
  {
   "id": "o6",
   "who": "S",
   "kind": "speak",
   "start": 99.65,
   "end": 101.23,
   "text": "אָז מִי פֹּה הַחֲמוֹר?",
   "syll": 5
  },
  {
   "id": "o7",
   "who": "T",
   "kind": "speak",
   "start": 101.86,
   "end": 103.5,
   "text": "תְּחַיֵּךְ. אֲנַחְנוּ בְּשִׁדּוּר.",
   "syll": 6
  }
 ],
